def nombre_boites(quantite, capacite):
    if type(quantite) is not int or type(capacite) is not int:
        raise TypeError("deux entiers attendus")
    if quantite < 0:
        raise ValueError("quantité négative")
    if capacite <= 0:
        raise ValueError("capacité strictement positive attendue")
    return (quantite + capacite - 1) // capacite

