def preparer_commande(lignes):
    total = 0
    for numero, ligne in enumerate(lignes, start=1):
        quantite = ligne["quantite"]
        if type(quantite) is not int:
            raise TypeError(f"Ligne {numero} : entier attendu")
        if quantite < 0:
            raise ValueError(f"Ligne {numero} : quantité négative")
        total += quantite
    return {"lignes": len(lignes), "total": total}

